suppressPackageStartupMessages({library(ComplexHeatmap);library(circlize);library(grid);library(jsonlite)})
source(file.path(dirname(normalizePath(commandArgs(TRUE)[1])),'native_export.R'));d<-read.csv(file.path(B,'input.csv'),check.names=FALSE,na.strings='');stopifnot(nrow(d)==171,!anyDuplicated(d$patient_id))
colhist<-c(LUAD='#CFB87C','Non-LUAD'='#8FC4B9');colstage<-c(I='#E7EAF2',II='#81ABC7',III='#355D8C');colsub<-c('invasive mucinous'='#E5B576',lepidic='#B5CFDF',papillary='#648CB3',acinar='#BCD39F',cribriform='#80AE7B',micropapillary='#D99E9A',solid='#C75C58');colevent<-c(None='#ECEDEC','EGFR mutated'='#774C92','MET exon 14 skipped'='#C6AE71');d$oncogenic_event[is.na(d$oncogenic_event)]<-'None';tc<-colorRamp2(c(5,60,120),c('#FFFFFF','#AAAAC2','#3E4677'));sm<-colorRamp2(c(0,150,300),c('#FFFFFF','#9F9F9F','#3C4146'))
# Each annotation is a one-dimensional track; it is not a rectangular data matrix.
tr<-HeatmapAnnotation(`ctDNA (PPM)`=anno_barplot(d$mrd_ctDNA_ppm_log,ylim=c(0,5.5),height=unit(17,'mm'),gp=gpar(fill=ifelse(d$mrd_status=='Detected','#9CCEE6','#C5C8CA'),col=NA),border=TRUE,axis_param=list(at=0:5,labels=c('0','10','100','1,000','10,000','100,000'),gp=gp())),`Tumor molecules/mL`=anno_barplot(d$mol_ml_peudolog,ylim=c(0,max(d$mol_ml_peudolog,na.rm=TRUE)*1.03),height=unit(10,'mm'),gp=gpar(fill='#425E8E',col=NA),border=TRUE,axis_param=list(at=log10(c(0,10,1000,100000)+1),labels=c('0','10','1,000','100,000'),gp=gp())),Histology=d$main_histology,`pTNM stage`=d$Stage,`Tumor size (mm)`=d$lesion1_size_pathology,`Smoking (pack-years)`=d$pack_years_truncated,`LUAD subtype`=d$luad_subtype,`Oncogenic event`=d$oncogenic_event,`Input cfDNA (ng)`=anno_barplot(d$cfdna_input_ng,height=unit(12,'mm'),gp=gpar(fill='#B3A18E',col=NA),axis_param=list(at=c(0,20,40),labels=c('0','20','40'),gp=gp()),border=TRUE),col=list(Histology=colhist,`pTNM stage`=colstage,`Tumor size (mm)`=tc,`Smoking (pack-years)`=sm,`LUAD subtype`=colsub,`Oncogenic event`=colevent),na_col='#F4F4F2',simple_anno_size=unit(1.8,'mm'),gap=unit(.5,'mm'),annotation_name_side='right',annotation_name_gp=gp(),annotation_name_offset=unit(1.5,'mm'),show_legend=FALSE)
leg<-function(t,c,ncol=1)Legend(title=t,labels=names(c),legend_gp=gpar(fill=c,col=NA),ncol=ncol,grid_width=unit(2,'mm'),grid_height=unit(2,'mm'),title_gp=gp(),labels_gp=gp(),gap=unit(2,'mm'))
lgs<-list(leg('Histology',colhist),leg('pTNM stage',colstage),Legend(title='Tumor size (mm)',col_fun=tc,at=c(5,60,120),direction='horizontal',legend_width=unit(24,'mm'),title_gp=gp(),labels_gp=gp()),Legend(title='Smoking (pack-years)',col_fun=sm,at=c(0,150,300),direction='horizontal',legend_width=unit(24,'mm'),title_gp=gp(),labels_gp=gp()),leg('LUAD subtype',setNames(colsub,tools::toTitleCase(names(colsub))),2),leg('Oncogenic event',colevent),leg('ctDNA (PPM)',c(Detected='#9CCEE6','Not detected'='#C5C8CA')))
draw_figure<-function(){
 pushViewport(viewport(x=unit(6,'mm'),y=unit(hh-6,'mm'),width=unit(138,'mm'),height=unit(59,'mm'),just=c('left','top')))
 draw(tr%v%NULL,newpage=FALSE,padding=unit(c(0,0,0,0),'mm'));loc<-new.env();decorate_annotation('Input cfDNA (ng)',{a<-deviceLoc(unit(0,'npc'),unit(0,'npc'),valueOnly=TRUE);b<-deviceLoc(unit(1,'npc'),unit(0,'npc'),valueOnly=TRUE);loc$x<-a$x*25.4;loc$w<-(b$x-a$x)*25.4;loc$y<-a$y*25.4});upViewport(0)
 # Only nine patient identifiers are labeled; complete ordered IDs remain in input.csv.
 ii<-seq(1,171,by=20);grid.text(d$patient_id[ii],x=unit(loc$x+(ii-.5)*loc$w/171,'mm'),y=unit(loc$y-1.8,'mm'),rot=90,just=c('right','center'),gp=gp())
 pk<-packLegend(list=lgs,direction='horizontal',max_width=unit(175,'mm'),row_gap=unit(3,'mm'),column_gap=unit(4,'mm'));draw(pk,x=unit(6,'mm'),y=unit(5,'mm'),just=c('left','bottom'))
 write_json(list(ordered_patient_ids=d$patient_id,annotation_track_mm=1.8,labeled_patient_ids=d$patient_id[ii],display='All171 patients present; tick identifiers thinned for legibility, full ordered ID mapping retained'),file.path(B,'track-order.json'),pretty=TRUE,auto_unbox=TRUE)
}
export_native(draw_figure,'grid')
